import {SpatialAudio} from './spatial-audio.js';
import {MUSIC_TRACKS,SAMPLE_NAMES} from './sound-pack.js';
export const permittedVoice=v=>/\b(?:rishi|moira)\b/i.test(v?.name??'');
export function preferredVoice(voices,selected='',role='commentary'){const allowed=voices.filter(permittedVoice);return allowed.find(v=>v.voiceURI===selected)||allowed.find(v=>new RegExp(role==='pain'?'\\brishi\\b':'\\bmoira\\b','i').test(v.name))||allowed[0]||null;}
// Recorded music and foley load once. Game simulation never waits on audio downloads.
export class GameAudio {
 constructor(settings,env=globalThis){this.settings=settings;this.env=env;this.mode=null;this.nodes=new Set();this.duck=1;this.tracks=new Map();this.samples=new Map();this.offsets=new Map();this.assetJobs=new Map();}
 unlock(){try{this.context??=new(this.env.AudioContext||this.env.webkitAudioContext)();if(!this.bus){this.bus=this.context.createGain();this.bus.gain.value=0;this.bus.connect(this.context.destination);}if(['suspended','interrupted'].includes(this.context.state))Promise.resolve(this.context.resume()).then(()=>this.sync(this.desiredMode??null),()=>{});this.loadAssets();return this.context;}catch{return null;}}
 async decode(file){let timer;try{return await Promise.race([(async()=>{const response=await this.env.fetch('assets/audio/'+file);if(!response.ok)throw Error('Audio download failed');return this.context.decodeAudioData(await response.arrayBuffer());})(),new Promise((_,reject)=>{timer=this.env.setTimeout?.(()=>reject(Error('Audio download timed out')),15000);})]);}finally{this.env.clearTimeout?.(timer);}}
 loadAssets(retry=false){if(!this.env.fetch||!this.context?.decodeAudioData)return;if(retry){for(const [key,value]of this.assetJobs)if(value==='failed')this.assetJobs.delete(key);}
  for(const [mode,file]of Object.entries(MUSIC_TRACKS)){const key='music:'+mode;if(this.assetJobs.has(key))continue;this.assetJobs.set(key,'loading');this.decode(file).then(buffer=>{this.tracks.set(mode,buffer);this.assetJobs.set(key,'ready');this.sync(this.desiredMode??null);},()=>this.assetJobs.set(key,'failed'));}
  for(const name of SAMPLE_NAMES){const key='effect:'+name;if(this.assetJobs.has(key))continue;this.assetJobs.set(key,'loading');this.decode(name+'.mp3').then(buffer=>{this.samples.set(name,buffer);this.assetJobs.set(key,'ready');},()=>this.assetJobs.set(key,'failed'));}
 }
 sync(mode){if(!this.settings().sound)this.stopEffects();this.desiredMode=mode;const next=this.settings().music&&this.context?.state==='running'?mode:null;if(next!==this.mode){this.stopMusic();this.mode=next;}if(next&&!this.trackSource&&this.tracks.has(next))this.startTrack(next);this.volume();}
 startTrack(mode){const c=this.context,buffer=this.tracks.get(mode),source=c.createBufferSource(),fade=c.createGain();source.buffer=buffer;source.loop=true;source.loopStart=0;source.loopEnd=buffer.duration;source.connect(fade);fade.connect(this.bus);fade.gain.setValueAtTime(0,c.currentTime);fade.gain.setTargetAtTime(1,c.currentTime,.08);const offset=(this.offsets.get(mode)??0)%buffer.duration;source.start(c.currentTime,offset);this.trackSource=source;this.trackFade=fade;this.trackStarted=c.currentTime;this.trackOffset=offset;this.nodes.add(source);source.onended=()=>{source.disconnect();fade.disconnect();this.nodes.delete(source);};}
 volume(){if(!this.bus)return;const target=this.mode?this.settings().musicVolume*1.4*this.duck:0;if(target===this.gainTarget)return;this.gainTarget=target;this.bus.gain.setTargetAtTime(target,this.context.currentTime,.06);}
 stopMusic(){if(this.trackSource){const source=this.trackSource;this.offsets.set(this.mode,(this.trackOffset+Math.max(0,this.context.currentTime-this.trackStarted))%source.buffer.duration);this.trackSource=null;try{source.stop();}catch{}source.disconnect();this.trackFade?.disconnect();this.nodes.delete(source);}this.mode=null;this.volume();}
 musicStatus(){if(this.trackSource)return 'playing';if(this.assetJobs.get('music:'+(this.desiredMode??'arena'))==='failed')return 'failed';return 'loading';}
 effect(type,position=null){if(this.effectsDisabled||!this.settings().sound||this.context?.state!=='running')return false;this.spatial??=new SpatialAudio(this.context,this.samples);if(this.listenerView)this.spatial.listener(...this.listenerView);return this.spatial.effect(type,position);}
 listener(camera,solids,water=[]){this.listenerView=[camera,solids];if(!this.effectsDisabled&&this.settings().sound&&this.context?.state==='running'){this.spatial??=new SpatialAudio(this.context,this.samples);this.spatial.listener(camera,solids);this.spatial.ambience(water);}else this.spatial?.listener(camera,solids);}
 stopEffects(){this.spatial?.stop();}
 effectsEnabled(value){this.effectsDisabled=!value;if(!value)this.stopEffects();else this.spatial?.enabled(true);}
 stopVoice(){if(this.voiceSource){const source=this.voiceSource;this.voiceSource=null;try{source.stop();}catch{}}this.env.clearTimeout?.(this.voiceTimer);this.utterance=null;try{this.env.speechSynthesis?.cancel();}catch{}this.duck=1;this.volume();}
 pain(){const now=this.env.performance?.now?.()??Date.now();if(now<(this.nextPain??0))return false;const lines=['Ooh!','Argh!','Ouch!','Oh my God, what are you doing?'];const spoken=this.speak(lines[(this.painIndex??0)%lines.length],{role:'pain'});if(spoken){this.painIndex=(this.painIndex??0)+1;this.nextPain=now+4500;}return spoken;}
 speak(text,{force=false,role='commentary'}={}){if(!text?.trim())return false;const now=this.env.performance?.now?.()??Date.now();if(!force&&role!=='pain'&&(now<(this.nextVoice??0)||text===this.lastVoice))return false;if(this.voiceSource&&!force)return false;if(!this.settings().voice||this.settings().voiceVolume<=0||!this.env.speechSynthesis||!this.env.SpeechSynthesisUtterance)return false;const synth=this.env.speechSynthesis;if((this.utterance||synth.speaking)&&!force)return false;try{if(force)this.stopVoice();const voice=preferredVoice(synth.getVoices(),this.settings().voiceName,role);if(!voice)return false;const u=new this.env.SpeechSynthesisUtterance(text);u.voice=voice;u.lang=voice.lang;u.rate=role==='pain'?1.08:1;u.pitch=1;u.volume=this.settings().voiceVolume;this.utterance=u;u.onstart=()=>{if(this.utterance!==u)return;this.duck=.28;this.volume();};u.onend=u.onerror=()=>{if(this.utterance!==u)return;this.env.clearTimeout?.(this.voiceTimer);this.utterance=null;this.duck=1;this.volume();};synth.speak(u);this.lastVoice=text;this.nextVoice=now+22000+Math.random()*12000;this.voiceTimer=this.env.setTimeout?.(()=>{if(this.utterance===u)this.stopVoice();},Math.max(5000,text.length*140));return true;}catch{this.utterance=null;this.duck=1;this.volume();return false;}}
}
